referenceSolution:
function fetchScore(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id < 0) reject(new Error('id tidak valid: ' + id));
      else resolve(id * 10);
    }, 10);
  });
}

async function totalScore(ids) {
  try {
    const scores = await Promise.all(ids.map(fetchScore));
    return scores.reduce((sum, s) => sum + s, 0);
  } catch (e) {
    return null;
  }
}

